const tiered = inputs.creditScores.map((s) => {
  let tier = 'SUBPRIME';
  let maxLimit = 5000;
  if (s.creditScore >= 740) {
    tier = 'PRIME';
    maxLimit = 50000;
  } else if (s.creditScore >= 670) {
    tier = 'NEAR_PRIME';
    maxLimit = 25000;
  } else if (s.creditScore >= 580) {
    tier = 'ACCEPTABLE';
    maxLimit = 12000;
  }
  return {
    ...s,
    tier,
    maxLimit,
  };
});
return { tieredDecisions: tiered };
```

